```javascript
import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, Color, Vector3 } from 'three/webgpu';
import { uv, mix, vec3, smoothstep, vec2, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;
  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };
  const ink = new Color(colors.ink);
  const paper = new Color(colors.paper);
  const accent = new Color(colors.accent);
  const surface = new Color(colors.surface);

  // Panel plane dimensions — a label card
  const panelW = 2.6;
  const panelH = 0.7;
  const panelGeo = new PlaneGeometry(panelW, panelH, 1, 1);

  // Brushed metal texture
  const metalUrl = config.imageUrl ?? '/prism-assets/chrome/brushed-metal.map.png';
  let metalTex = null;
  const mat = new MeshBasicNodeMaterial({ transparent: true });
  mat.colorNode = mix(vec3(surface), vec3(ink), smoothstep(float(0.0), float(1.0), uv().y));
  mat.opacityNode = float(1.0);

  ctx.textureLoader.loadTexture(metalUrl).then((tex) => {
    metalTex = tex;
    tex.colorSpace = ctx.THREE.SRGBColorSpace;
    tex.wrapS = ctx.THREE.RepeatWrapping;
    tex.wrapT = ctx.THREE.RepeatWrapping;
    tex.repeat.set(2.2, 0.7);
    mat.map = tex;
    // Compose: metal texture tinted by gradient
    const metalSample = vec3(metalTex);
    const grad = mix(vec3(surface), vec3(ink), smoothstep(float(0.0), float(1.0), uv().y));
    mat.colorNode = mix(grad, metalSample.mul(vec3(0.55)), float(0.6));
    mat.needsUpdate = true;
  });

  const panel = new Mesh(panelGeo, mat);
  panel.position.set(0, 0, 0);
  group.add(panel);

  // Accent edge bar — thin red line at bottom of label
  const barGeo = new PlaneGeometry(panelW * 0.92, 0.018);
  const barMat = new MeshBasicNodeMaterial({ transparent: true });
  barMat.colorNode = vec3(accent);
  barMat.opacityNode = float(0.9);
  const bar = new Mesh(barGeo, barMat);
  bar.position.set(0, -panelH * 0.5 + 0.06, 0.001);
  group.add(bar);

  // Text — "Collection 2"
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((it) => it.role === 'headline') || items[0] || { text: 'Collection 2' };
  const fontSize = headlineItem.typography?.fontSize ?? 39;

  const label = ctx.fontAtlas.createText(String(headlineItem.text), {
    fontSize: fontSize,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 2,
  });
  // Position text in front of panel; estimate width to center
  label.position.set(0, 0.015, 0.005);
  group.add(label);

  // Subtle entrance — fade-up (no interactivity per spec, but entrance allowed)
  group.userData.handlers = {};

  const tl = gsap.timeline();
  tl.from(group.position, { y: 0.18, duration: 0.6, ease: 'power3.out' }, 0);
  tl.from(group.scale, { x: 0.98, y: 0.98, duration: 0.7, ease: 'power3.out' }, 0);

  // Settle overshoot
  gsap.fromTo(group.scale,
    { x: 1.0, y: 1.0 },
    { x: 1.04, y: 1.04, duration: 0.45, ease: 'power2.out', yoyo: true, repeat: 1, delay: 0.6 });

  userData_cleanup();

  function userData_cleanup() {
    group.userData.cleanup = () => {
      tl.kill();
      gsap.killTweensOf(group.position);
      gsap.killTweensOf(group.scale);
      panelGeo.dispose();
      barGeo.dispose();
      mat.dispose();
      barMat.dispose();
      if (metalTex) metalTex.dispose();
    };
  }

  return group;
}
